[{"order":1,"type":"heading","text":"Shader Effects and Metal Integration in SwiftUI"},{"order":2,"type":"paragraph","text":"Apple has revolutionized custom UI development in SwiftUI by introducing direct integration with Metal shaders. Through the layer effect and color effect modifiers, developers can now write custom MSL (Metal Shading Language) code to manipulate SwiftUI views with GPU acceleration."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"macOS 14.0+ / iOS 17.0+ deployment target."},{"order":5,"type":"bullet_point","text":"Xcode 15.0 or later."},{"order":6,"type":"bullet_point","text":"Basic understanding of Metal Shading Language (MSL) and SwiftUI."},{"order":7,"type":"subheading","text":"Step 1: Writing the Metal Shading Language Code"},{"order":8,"type":"paragraph","text":"Create a new file named "CustomShaders.metal" in your project. This file will contain your custom pixel manipulation logic."},{"order":9,"type":"code","text":"#include <metal_stdlib>
using namespace metal;

[[ stitchable ]] half4 waveEffect(float2 position, half4 color, float time) {
    float2 p = position;
    p.y += sin(p.x * 0.05 + time) * 10.0;
    return color;
}"},{"order":10,"type":"subheading","text":"Step 2: Integrating the Shader in SwiftUI"},{"order":11,"type":"paragraph","text":"Now, we will consume the Metal shader inside a SwiftUI view using the layerEffect modifier alongside a TimelineView to drive continuous animations."},{"order":12,"type":"code","text":"struct WaveView: View {
    var body: some View {
        TimelineView(.animation) { context in
            let time = context.date.timeIntervalSinceReferenceDate
            Text("Hello, Metal!")
                .font(.system(size: 40, weight: .bold))
                .foregroundColor(.white)
                .layerEffect(
                    ShaderLibrary.waveEffect(.float(time)),
                    maxSampleOffset: CGSize(width: 20, height: 20)
                )
        }
    }
}"},{"order":13,"type":"subheading","text":"Best Practices"},{"order":14,"type":"bullet_point","text":"Always specify a realistic maxSampleOffset to prevent rendering glitches and allow SwiftUI to correctly calculate bounding boxes."},{"order":15,"type":"bullet_point","text":"Use colorEffect for operations that only modify color without shifting pixels, as it is heavily optimized for per-pixel transformations."}]
